//! Whether a recursive deletion inside the repository would destroy work: files git tracks (source,
//! not build output) or files git has not saved yet. Ignored output such as `node_modules` or
//! `target` is regenerable and stays routine.

use std::path::Path;
use std::process::{Command, Stdio};

/// Directories that are regenerated by tools, used when the repository is not a git working copy.
const REGENERABLE: &[&str] = &[
    "node_modules",
    "dist",
    "build",
    "target",
    "out",
    "coverage",
    ".next",
    ".nuxt",
    ".turbo",
    ".cache",
    "__pycache__",
    ".pytest_cache",
    ".venv",
    "venv",
    ".gradle",
    "bin",
    "obj",
    "test-results",
];

/// `true` when recursively deleting `target` (relative to `root`, or absolute inside it) would
/// remove tracked or not-yet-saved files. Unexpanded variables cannot be resolved and are skipped.
pub fn holds_work(root: &Path, target: &str) -> bool {
    if target.contains('$') || target.contains('%') || target.trim().is_empty() {
        return false;
    }
    match git_listed(root, target) {
        Some(listed) => listed,
        None => {
            let path = root.join(target);
            path.exists() && !is_regenerable(target)
        }
    }
}

/// Whether git lists tracked or untracked (not ignored) files under `target`; `None` when git
/// cannot answer (not a repository, git missing).
fn git_listed(root: &Path, target: &str) -> Option<bool> {
    let output = Command::new("git")
        .args(["ls-files", "--cached", "--others", "--exclude-standard", "--", target])
        .current_dir(root)
        .stdin(Stdio::null())
        .stderr(Stdio::null())
        .output()
        .ok()?;
    output.status.success().then(|| !output.stdout.iter().all(u8::is_ascii_whitespace))
}

fn is_regenerable(target: &str) -> bool {
    let unified = target.replace('\\', "/");
    let last = unified.trim_end_matches(['/', '*']).rsplit('/').next().unwrap_or_default();
    REGENERABLE.contains(&last.to_ascii_lowercase().as_str())
}

#[cfg(test)]
mod tests {
    use std::fs;
    use std::process::Command;

    use tempfile::TempDir;

    use super::holds_work;

    fn git(root: &std::path::Path, args: &[&str]) {
        let ok = Command::new("git").args(args).current_dir(root).output().expect("git").status;
        assert!(ok.success(), "git {args:?}");
    }

    #[test]
    fn tracked_and_unsaved_files_count_as_work_but_ignored_output_does_not() {
        let dir = TempDir::new().expect("tmp");
        let root = dir.path();
        git(root, &["init", "-q"]);
        fs::write(root.join(".gitignore"), "node_modules/\ndist/\n").expect("ignore");
        for (rel, body) in [
            ("src/a.ts", "a"),
            ("node_modules/x/i.js", "x"),
            ("dist/a.js", "a"),
            ("scratch/new.ts", "n"),
        ] {
            let path = root.join(rel);
            fs::create_dir_all(path.parent().expect("parent")).expect("dirs");
            fs::write(path, body).expect("write");
        }
        git(root, &["add", "src/a.ts", ".gitignore"]);
        assert!(holds_work(root, "src"), "tracked source");
        assert!(holds_work(root, "./src/"), "tracked source, dotted");
        assert!(holds_work(root, "scratch"), "untracked work");
        assert!(!holds_work(root, "node_modules"), "ignored dependencies");
        assert!(!holds_work(root, "dist"), "ignored build output");
        assert!(!holds_work(root, "missing"), "nothing there");
        assert!(!holds_work(root, "$BUILD_DIR"), "unexpanded variable");
    }

    #[test]
    fn outside_git_only_known_output_folders_are_routine() {
        let dir = TempDir::new().expect("tmp");
        let root = dir.path();
        for rel in ["src/a.ts", "node_modules/i.js"] {
            let path = root.join(rel);
            fs::create_dir_all(path.parent().expect("parent")).expect("dirs");
            fs::write(path, "x").expect("write");
        }
        assert!(holds_work(root, "src"));
        assert!(!holds_work(root, "node_modules"));
    }
}
